create table emily.action_item_team_members (
    id        number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by 1 cache 20
    noorder nocycle nokeep noscale not null enable,
    action_id number,
    user_id   number,
    role      varchar2(6 char) default 'MEMBER'
);

alter table emily.action_item_team_members
    add constraint action_item_team_members_con
        check ( role in ( 'LEAD', 'MEMBER' ) ) enable;

alter table emily.action_item_team_members
    add constraint team_id_pk primary key ( id )
        using index enable;


